-- кодирование строки для адреса (русские буквы и пробелы тоже)
function MKT.enc(s)
    return (tostring(s or ""):gsub("[^%w%-_%.~]", function(c)
        return string.format("%%%02X", c:byte())
    end))
end

-- цена с точками: 10000000 -> 10.000.000
function MKT.fmt(n)
    local s = tostring(math.floor(tonumber(n) or 0))
    local r = s:reverse():gsub("(%d%d%d)", "%1."):reverse()
    return (r:gsub("^%.", ""))
end

-- сколько прошло времени с публикации (created приходит в миллисекундах)
function MKT.age(ms)
    local mins = math.floor((os.time() * 1000 - (tonumber(ms) or 0)) / 60000)
    if mins < 1 then return "только что" end
    if mins < 60 then return mins .. " мин назад" end
    return math.floor(mins / 60) .. " ч назад"
end

-- личный код автора: нужен, чтобы удалять свои объявления. Сохраняется в папке config.
function MKT.get_token()
    if MKT.token_value then return MKT.token_value end
    local saved = read_file_raw(MKT.file_token)
    if saved then
        saved = saved:gsub("%s", "")
        if #saved >= 16 then
            MKT.token_value = saved
            return saved
        end
    end
    local chars = "abcdefghijklmnopqrstuvwxyz0123456789"
    math.randomseed(os.time() + math.floor(os.clock() * 1000))
    local t = {}
    for i = 1, 32 do
        local k = math.random(1, #chars)
        t[i] = chars:sub(k, k)
    end
    MKT.token_value = table.concat(t)
    if not doesDirectoryExist(getWorkingDirectory() .. "\\config") then
        createDirectory(getWorkingDirectory() .. "\\config")
    end
    write_file_raw(MKT.file_token, MKT.token_value)
    return MKT.token_value
end

-- ник своего персонажа
function MKT.nick()
    local ok, nick = pcall(function()
        local _, pid = sampGetPlayerIdByCharHandle(PLAYER_PED)
        return sampGetPlayerNickname(pid)
    end)
    if ok and type(nick) == "string" and nick ~= "" then return nick end
    return nil
end

function MKT.set_status(text, ok)
    MKT.status, MKT.status_ok = text, ok
end

-- какие способы связи с сервером есть на этом компьютере
MKT.VERSION = "v28"
MKT.ok_effil, MKT.effil = pcall(require, "effil")
MKT.ok_req = pcall(require, "requests")
MKT.method = ""
MKT.thread = nil
MKT.thread_action = nil
MKT.dl_log = ""

-- если в пути к игре есть русские буквы, скачивание в эту папку может не сработать: берём общую папку Windows
do
    local base = getWorkingDirectory() .. "\\config"
    local pub = os.getenv("PUBLIC")
    if base:find("[\128-\255]") and pub and pub ~= "" then
        MKT.file_resp = pub .. "\\arizona_market_resp.json"
    end
end

function MKT.yn(b)
    return b and "да" or "нет"
end

-- запрос к серверу. Способ 1: отдельный поток (effil + requests). Способ 2: скачивание файла.
function MKT.send(action, query)
    if MKT.loading then return end
    local url = MKT.base .. "/" .. action .. "?" .. query .. "&r=" .. os.time()
    MKT.loading, MKT.t0 = true, os.clock()
    MKT.set_status("Подождите...", true)

    if MKT.ok_effil and MKT.ok_req then
        local ok, th = pcall(function()
            return MKT.effil.thread(function(u)
                local requests = require("requests")
                local okr, resp = pcall(requests.request, "GET", u)
                if okr and type(resp) == "table" then
                    return true, tostring(resp.text or ""), tonumber(resp.status_code) or 0
                end
                return false, tostring(resp), 0
            end)(url)
        end)
        if ok and th then
            MKT.thread, MKT.thread_action, MKT.method = th, action, "поток"
            return
        end
    end

    MKT.method = "файл"
    if not downloadUrlToFile or not dlstatus then
        MKT.loading = false
        MKT.set_status("В вашей версии MoonLoader нет загрузки из интернета", false)
        return
    end
    local dest = MKT.file_resp
    os.remove(dest)
    MKT.dl_log = ""
    defer(function()
        local ok, started = pcall(downloadUrlToFile, url, dest, function(id, status)
            if #MKT.dl_log < 40 then MKT.dl_log = MKT.dl_log .. tostring(status) .. " " end
            if status == dlstatus.STATUSEX_ENDDOWNLOAD then
                MKT.result = { action = action, file = dest }
            end
        end)
        if not ok or started == false then
            MKT.loading = false
            MKT.set_status("Игра не смогла начать скачивание: " .. tostring(started), false)
        end
    end)
end

-- забирает ответ сервера, если он пришёл
function MKT.handle()
    if MKT.thread then
        local okS, status, err = pcall(function() return MKT.thread:status() end)
        if not okS then
            MKT.thread = nil
            MKT.result = { action = MKT.thread_action, text = "", err = "поток: " .. tostring(status) }
        elseif status == "completed" then
            local okG, success, text, code = pcall(function() return MKT.thread:get() end)
            MKT.thread = nil
            if okG and success == true then
                MKT.result = { action = MKT.thread_action, text = text, code = code }
            else
                MKT.result = { action = MKT.thread_action, text = "", err = tostring(okG and text or success) }
            end
        elseif status == "failed" or status == "canceled" then
            MKT.thread = nil
            MKT.result = { action = MKT.thread_action, text = "", err = tostring(err or status) }
        end
    end

    local r = MKT.result
    if r then
        MKT.result = nil
        MKT.loading = false
        local chain = (r.action == "delete") and MKT.chain_add or nil
        MKT.chain_add = nil
        local raw
        if r.file then raw = read_file_raw(r.file) else raw = r.text end
        local data = nil
        if raw and raw ~= "" and json_ok(raw) then data = decodeJson(raw) end
        if type(data) ~= "table" then
            local head = raw and (raw:sub(1, 50):gsub("[\r\n]", " ")) or "нет"
            local info = "Нет ответа. Способ: " .. MKT.method
                .. ", ответ: " .. (raw and (#raw .. " байт") or "файла нет")
            if r.code then info = info .. ", код: " .. tostring(r.code) end
            if r.err then info = info .. ", ошибка: " .. tostring(r.err) end
            if r.file then info = info .. ", статусы загрузки: " .. MKT.dl_log end
            if raw and raw ~= "" then info = info .. ", начало: " .. head end
            MKT.set_status(info, false)
        elseif data.error then
            local msg = MKT.errors[data.error]
            if not msg or data.error == "server" then
                msg = (msg or MKT.errors.server) .. " | " .. tostring(data.detail or raw:sub(1, 150))
            end
            MKT.set_status(msg, false)
        elseif r.action == "list" then
            MKT.items = data.items or {}
            MKT.set_status("Объявлений: " .. #MKT.items, true)
            MKT.check_watch()
        elseif r.action == "add" then
            MKT.set_status("Объявление опубликовано", true)
            MKT.need_list = true
        elseif r.action == "delete" and chain then
            MKT.send("add", chain)
        elseif r.action == "delete" then
            MKT.set_status("Объявление удалено", true)
            MKT.need_list = true
        end
    end

    if MKT.loading and os.clock() - MKT.t0 > 25 then
        MKT.loading = false
        MKT.thread = nil
        MKT.set_status("Нет ответа от сервера за 25 секунд. Способ: " .. MKT.method, false)
    end
end

-- кнопка-таблетка: скругление, подсветка при наведении, акцентная если активна
function MKT.pill(id, label, active, w, h)
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton("##pill_" .. id, imgui.ImVec2(w, h))
    local hov = imgui.IsItemHovered()
    local held = imgui.IsItemActive()
    local a = UI_CFG.accent
    local r, g, b, al
    if active then
        r, g, b, al = a[1], a[2], a[3], held and 0.85 or 1.0
    else
        r, g, b, al = 0.15, 0.15, 0.20, 0.95
        if hov then r, g, b = 0.24, 0.24, 0.31 end
    end
    local p2 = imgui.ImVec2(p.x + w, p.y + h)
    dl:AddRectFilled(p, p2, col32(r, g, b, al), h / 2)
    local ts = imgui.CalcTextSize(label)
    dl:AddText(imgui.ImVec2(p.x + (w - ts.x) / 2, p.y + (h - ts.y) / 2), col32(1, 1, 1, 1), label)
    return clicked
end

-- плавно переливающийся цвет (сдвиг фазы даёт разные оттенки одновременно)
function MKT.rainbow(offset)
    local t = os.clock() * 0.9 + (offset or 0)
    return imgui.ImVec4(
        0.55 + 0.45 * math.sin(t),
        0.55 + 0.45 * math.sin(t + 2.094),
        0.55 + 0.45 * math.sin(t + 4.188),
        1.0)
end

-- затемнённый переливающийся цвет для кнопок (текст на нём читается)
function MKT.rainbow_btn(offset)
    local c = MKT.rainbow(offset)
    return imgui.ImVec4(c.x * 0.45, c.y * 0.45, c.z * 0.45, 1.0)
end

-- выборка объявлений: вкладка, поиск, валюта, цена от/до, сортировка
function MKT.view(q)
    local pmin = tonumber((ffi.string(MKT.buf_pmin):gsub("[%s%.,]", "")))
    local pmax = tonumber((ffi.string(MKT.buf_pmax):gsub("[%s%.,]", "")))
    local fc = MKT.fcur_opts[MKT.fcur]
    local out = {}
    for _, it in ipairs(MKT.items) do
        local okType = MKT.tab == "all" or MKT.tab == it.type
        if MKT.tab == "fav" then okType = MKT.favs[tostring(it.id)] == true end
        if MKT.tab == "mine" then okType = it.mine == true end
        -- каждое слово из поиска должно встречаться в названии: "нимб 5" найдёт "Нимб +5"
        local okName = true
        if q ~= "" then
            local iname = ru_lower(tostring(it.item or ""))
            for word in q:gmatch("%S+") do
                if not iname:find(word, 1, true) then okName = false break end
            end
        end
        local okCur = fc == "Все" or (it.currency or "VC") == fc
        local pr = tonumber(it.price) or 0
        local okMin = not pmin or pr >= pmin
        local okMax = not pmax or pr <= pmax
        local hrs = MKT.ages[MKT.age_idx][2]
        local okAge = hrs == 0 or (os.time() * 1000 - (tonumber(it.created) or 0)) <= hrs * 3600000
        if okType and okName and okCur and okMin and okMax and okAge then
            out[#out + 1] = it
        end
    end
    local key = MKT.sorts[MKT.sort][1]
    table.sort(out, function(x, y)
        if key == "cheap" then return (tonumber(x.price) or 0) < (tonumber(y.price) or 0) end
        if key == "exp" then return (tonumber(x.price) or 0) > (tonumber(y.price) or 0) end
        if key == "name" then return ru_lower(tostring(x.item or "")) < ru_lower(tostring(y.item or "")) end
        return (tonumber(x.created) or 0) > (tonumber(y.created) or 0)
    end)
    return out
end

-- что запоминаем между запусками: сервер, валюта, контакт, соцсеть
function MKT.prefs_key()
    return MKT.social .. "|" .. MKT.home .. "|" .. MKT.currency .. "|" .. ffi.string(MKT.buf_contact) .. "|" .. ffi.string(MKT.buf_watch) .. "|" .. ffi.string(MKT.buf_pass)
end

function MKT.load_prefs()
    local raw = read_file_raw(MKT.file_prefs)
    if not raw or not json_ok(raw) then return end
    local d = decodeJson(raw)
    if type(d) ~= "table" then return end
    if type(d.social) == "number" and d.social >= 1 and d.social <= #MKT.socials then MKT.social = d.social end
    if type(d.home) == "number" and d.home >= 1 and d.home <= #MKT.home_servers then MKT.home = d.home end
    if type(d.currency) == "number" and d.currency >= 1 and d.currency <= #MKT.currencies then MKT.currency = d.currency end
    if type(d.contact) == "string" then ffi.copy(MKT.buf_contact, d.contact:sub(1, 119)) end
    if type(d.watch) == "string" then ffi.copy(MKT.buf_watch, d.watch:sub(1, 119)) end
    if type(d.pass) == "string" then ffi.copy(MKT.buf_pass, d.pass:sub(1, 63)) end
end

function MKT.save_prefs()
    local ok, data = pcall(encodeJson, {
        social = MKT.social,
        home = MKT.home,
        currency = MKT.currency,
        contact = ffi.string(MKT.buf_contact),
        watch = ffi.string(MKT.buf_watch),
        pass = ffi.string(MKT.buf_pass),
    })
    if not ok then return end
    if not doesDirectoryExist(getWorkingDirectory() .. "\\config") then
        createDirectory(getWorkingDirectory() .. "\\config")
    end
    write_file_raw(MKT.file_prefs, data)
end

-- избранное: id объявлений, сохраняются в папке config
function MKT.load_favs()
    local raw = read_file_raw(MKT.file_favs)
    if not raw or not json_ok(raw) then return end
    local d = decodeJson(raw)
    if type(d) ~= "table" then return end
    for _, id in ipairs(d) do MKT.favs[tostring(id)] = true end
end

function MKT.save_favs()
    local list = {}
    for id, on in pairs(MKT.favs) do
        if on then list[#list + 1] = id end
    end
    local ok, data = pcall(encodeJson, list)
    if not ok then return end
    if not doesDirectoryExist(getWorkingDirectory() .. "\\config") then
        createDirectory(getWorkingDirectory() .. "\\config")
    end
    write_file_raw(MKT.file_favs, data)
end

-- уведомление в чат: новое объявление по словам из «Следить за»
-- первая загрузка только запоминает объявления, без уведомлений
function MKT.check_watch()
    local first = MKT.seen == nil
    MKT.seen = MKT.seen or {}
    local words = {}
    for w in ru_lower(ffi.string(MKT.buf_watch)):gmatch("[^,]+") do
        w = w:gsub("^%s+", ""):gsub("%s+$", "")
        if w ~= "" then words[#words + 1] = w end
    end
    for _, it in ipairs(MKT.items) do
        local id = tostring(it.id)
        if not MKT.seen[id] then
            MKT.seen[id] = true
            if not first and not it.mine and #words > 0 then
                local name = ru_lower(tostring(it.item or ""))
                for _, w in ipairs(words) do
                    if name:find(w, 1, true) then
                        sampAddChatMessage(u8:decode("{33AAFF}[Маркет] {FFFFFF}Новое объявление: {FFCC33}" .. tostring(it.item)
                            .. "{FFFFFF} - " .. MKT.fmt(it.price) .. " " .. tostring(it.currency or "VC")
                            .. " ({33AAFF}" .. tostring(it.nick) .. "{FFFFFF})"), -1)
                        break
                    end
                end
            end
        end
    end
end

-- правка своего объявления: заполняем форму «Выставить» данными объявления
function MKT.start_edit(it)
    MKT.edit_id = it.id
    MKT.kind = it.type == "buy" and "buy" or "sell"
    -- длину обрезаем под размер поля: иначе запись выходит за границу памяти и игра падает
    ffi.copy(MKT.buf_item, tostring(it.item or ""):sub(1, 63))
    ffi.copy(MKT.buf_price, tostring(math.floor(tonumber(it.price) or 0)):sub(1, 23))
    ffi.copy(MKT.buf_contact, tostring(it.contact or ""):sub(1, 119))
    -- КД вынимаем из описания обратно в выпадающий список, чтобы не дублировать его
    local desc = tostring(it.desc or "")
    local code = desc:match(" | КД: (%d+) %(%-%d+%)")
    desc = (desc:gsub(" | КД: %d+ %(%-%d+%)", ""))
    ffi.copy(MKT.buf_desc, desc:sub(1, 299))
    MKT.cd_idx = 1
    for i, c in ipairs(MKT.cd_list) do
        if c[1] == code then MKT.cd_idx = i + 1 end
    end
    for i, name in ipairs(MKT.home_servers) do
        if name == it.home then MKT.home = i end
    end
    for i, c in ipairs(MKT.currencies) do
        if c.code == it.currency then MKT.currency = i end
    end
    MKT.want_create = true
end

-- публикация: при правке сначала удаляем старое объявление, потом публикуем новое
function MKT.queue_add(q)
    if MKT.edit_id then
        local id = MKT.edit_id
        MKT.edit_id = nil
        MKT.chain_add = q
        MKT.send("delete", "server=" .. MKT.enc(MKT.market) .. "&id=" .. MKT.enc(id)
            .. "&token=" .. MKT.enc(MKT.get_token()))
    else
        MKT.send("add", q)
    end
end

-- переливающаяся полоса сверху окна
function MKT.rainbow_bar()
    local dl = imgui.GetWindowDrawList()
    local pp = imgui.GetCursorScreenPos()
    local pw = imgui.GetContentRegionAvail().x
    local seg = 48
    local inset = 6
    local bw = pw - inset * 2
    for k = 0, seg - 1 do
        local x0 = pp.x + inset + bw * k / seg
        local x1 = pp.x + inset + bw * (k + 1) / seg
        local c = MKT.rainbow(k * 0.18)
        dl:AddRectFilled(imgui.ImVec2(x0, pp.y), imgui.ImVec2(x1, pp.y + 3), col32(c.x, c.y, c.z, 1.0))
    end
    imgui.Dummy(imgui.ImVec2(pw, 6))
end

-- собирает ссылку из выбранной соцсети и ника (можно вставить и готовую ссылку)
function MKT.build_contact(idx, s)
    local c = tostring(s or ""):gsub("%s", ""):gsub("^@", "")
    if c == "" then return "" end
    if c:find("^https?://") then return c end
    local host = MKT.socials[idx].host
    local bare = host:gsub("^https?://", "")
    if c:sub(1, #bare) == bare then c = c:sub(#bare + 1) end
    return host .. c
end

-- приводит контакт к ссылке: @ник -> t.me/ник, t.me/ник -> https://t.me/ник
function MKT.clean_contact(s)
    local c = tostring(s or ""):gsub("%s", "")
    if c == "" then return "" end
    if c:sub(1, 1) == "@" then c = "t.me/" .. c:sub(2) end
    if not c:find("^https?://") then c = "https://" .. c end
    return c
end

-- открывает ссылку в браузере или приложении (Windows)
function MKT.open_link(url)
    local u = tostring(url or ""):gsub('[&|<>"^]', "")
    if u == "" then return end
    os.execute('start "" "' .. u .. '"')
end

-- фильтр по названию (без учёта регистра, русские буквы тоже)
local function mkt_match(name, q)
    if q == "" then return true end
    return ru_lower(tostring(name or "")):find(q, 1, true) ~= nil
end

-- подсказки из таблицы цен: совпадения по названию
function MKT.suggest(q)
    local out = {}
    if q == "" then return out end
    for _, it in ipairs(items_list) do
        if it.item and mkt_match(it.item, q) then
            out[#out + 1] = it
            if #out >= 300 then break end
        end
    end
    return out
end

-- коллекционный предмет: в скобках метка Легендарный / Хлам / Редкий
function MKT.is_collectible(name)
    local n = ru_lower(tostring(name or ""))
    for grp in n:gmatch("%((.-)%)") do
        if grp:find("легендарн", 1, true) or grp:find("хлам", 1, true) or grp:find("редк", 1, true) then
            return true
        end
    end
    return false
end

-- описание для объявления: к тексту добавляем КД на тайники, если он выбран
function MKT.desc_with_cd()
    local d = (ffi.string(MKT.buf_desc):gsub("^%s+", ""):gsub("%s+$", ""))
    if MKT.is_collectible(ffi.string(MKT.buf_item)) and MKT.cd_idx > 1 then
        local c = MKT.cd_list[MKT.cd_idx - 1]
        d = d .. " | КД: " .. c[1] .. " (-" .. c[2] .. ")"
    end
    return d:sub(1, 300)
end

-- тело окна «Выставить предмет»
function MKT.draw_create_body(srv)
    local w = imgui.GetContentRegionAvail().x
    local half = (w - 8) / 2
    MKT.rainbow_bar()

    imgui.SetWindowFontScale(1.35)
    imgui.TextColored(MKT.rainbow(0), MKT.edit_id and "Изменить объявление" or "Выставить предмет")
    imgui.SetWindowFontScale(1.0)
    imgui.TextDisabled("Заполните поля и нажмите «Опубликовать»")
    imgui.Spacing()

    -- тип сделки
    imgui.Text("Тип сделки")
    for i, opt in ipairs({ { "Продаю", "sell" }, { "Куплю", "buy" } }) do
        if MKT.pill("kind_" .. opt[2], opt[1], MKT.kind == opt[2], half, 34) then
            MKT.kind = opt[2]
        end
        if i == 1 then imgui.SameLine() end
    end
    imgui.Spacing()

    -- предмет
    imgui.Text("Предмет")
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint("##cr_item", "Например: Нимб 5 звезд +16", MKT.buf_item, ffi.sizeof(MKT.buf_item))
    imgui.PopItemWidth()

    -- поиск предмета по таблице цен
    imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0.10, 0.10, 0.13, 1.0))
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint("##cr_csearch", "Поиск в таблице цен, например: нимб", MKT.buf_csearch, ffi.sizeof(MKT.buf_csearch))
    imgui.PopItemWidth()
    imgui.PopStyleColor(1)
    local cq = ru_lower(ffi.string(MKT.buf_csearch))
    cq = (cq:gsub("^%s+", ""):gsub("%s+$", ""))
    if cq ~= "" then
        local sugg = MKT.suggest(cq)
        imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.09, 0.09, 0.12, 0.96))
        imgui.BeginChild("##cr_sugg", imgui.ImVec2(-1, 170), true)
        if #sugg == 0 then
            imgui.TextDisabled("В таблице цен нет такого предмета")
        end
        for i, it in ipairs(sugg) do
            -- одна строка = один предмет; текст крупнее, без иконок (они могли вызывать падение)
            imgui.SetWindowFontScale(1.3)
            if imgui.Selectable(tostring(it.item) .. "##cr_sugg_" .. i, false) then
                ffi.copy(MKT.buf_item, tostring(it.item):sub(1, 63))
                MKT.buf_csearch[0] = 0
            end
            if imgui.IsItemHovered() then
                imgui.SetTooltip("Нажмите, чтобы выбрать")
            end
            imgui.SetWindowFontScale(1.0)
        end
        imgui.EndChild()
        imgui.PopStyleColor(1)
    end

    -- КД на тайники: появляется сразу под предметом, только у коллекционных
    if MKT.is_collectible(ffi.string(MKT.buf_item)) then
        imgui.Text("КД на тайники")
        imgui.PushItemWidth(-1)
        if imgui.BeginCombo("##cr_cd", MKT.cd_opts[MKT.cd_idx]) then
            for i, o in ipairs(MKT.cd_opts) do
                if imgui.Selectable(o .. "##cr_cd_" .. i, i == MKT.cd_idx) then
                    MKT.cd_idx = i
                end
            end
            imgui.EndCombo()
        end
        imgui.PopItemWidth()
    end

    -- цена и валюта
    imgui.Text("Цена")
    imgui.PushItemWidth(100)
    if imgui.BeginCombo("##cr_cur", MKT.currencies[MKT.currency].label) then
        for i, c in ipairs(MKT.currencies) do
            if imgui.Selectable(c.label .. "##cr_c" .. i, i == MKT.currency) then
                MKT.currency = i
            end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()
    imgui.SameLine()
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint("##cr_price", "Только цифры, например 1500000", MKT.buf_price, ffi.sizeof(MKT.buf_price))
    imgui.PopItemWidth()

    -- родной сервер
    imgui.Text("Родной сервер")
    imgui.PushItemWidth(-1)
    if imgui.BeginCombo("##cr_home", MKT.home_servers[MKT.home]) then
        for i, name in ipairs(MKT.home_servers) do
            if imgui.Selectable(name .. "##cr_h" .. i, i == MKT.home) then
                MKT.home = i
            end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()

    -- контакт
    imgui.Text("Контакт (обязательно)")
    imgui.PushItemWidth(120)
    if imgui.BeginCombo("##cr_social", MKT.socials[MKT.social].label) then
        for i, so in ipairs(MKT.socials) do
            if imgui.Selectable(so.label .. "##cr_so" .. i, i == MKT.social) then
                MKT.social = i
            end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()
    imgui.SameLine()
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint("##cr_contact", "", MKT.buf_contact, ffi.sizeof(MKT.buf_contact))
    imgui.PopItemWidth()

    -- описание
    imgui.Text("Описание (необязательно)")
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint("##cr_desc", "Торг, обмен, условия", MKT.buf_desc, ffi.sizeof(MKT.buf_desc))
    imgui.PopItemWidth()

    -- пароль ника: первый пароль задаёт владелец ника, дальше без него не выставить
    imgui.TextColored(imgui.ImVec4(1.0, 0.75, 0.3, 1.0), "Пароль для вашего ника (минимум 4 символа)")
    imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.75, 0.75, 0.8, 1.0))
    imgui.TextWrapped("ЗАПОМНИТЕ ПАРОЛЬ! Его нельзя восстановить или сменить. Без него не получится выставлять объявления с этим ником.")
    imgui.PopStyleColor(1)
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint("##cr_pass", "Например: мой пароль, не забыть!", MKT.buf_pass, ffi.sizeof(MKT.buf_pass))
    imgui.PopItemWidth()

    -- проверка заполнения
    local name = (ffi.string(MKT.buf_item):gsub("^%s+", ""):gsub("%s+$", ""))
    local price = tonumber((ffi.string(MKT.buf_price):gsub("[%s%.,]", "")))
    local contact = MKT.build_contact(MKT.social, ffi.string(MKT.buf_contact))
    local missing = {}
    if name == "" then missing[#missing + 1] = "предмет" end
    if not price or price <= 0 then missing[#missing + 1] = "цену" end
    if contact == "" then missing[#missing + 1] = "контакт" end
    if #ffi.string(MKT.buf_pass) < 4 then missing[#missing + 1] = "пароль (от 4 символов)" end
    imgui.Spacing()
    if #missing > 0 then
        imgui.TextColored(imgui.ImVec4(1.0, 0.5, 0.5, 1.0), "Нужно заполнить: " .. table.concat(missing, ", "))
    else
        imgui.TextColored(imgui.ImVec4(0.5, 1.0, 0.6, 1.0), "Всё заполнено, можно публиковать")
    end
    imgui.Spacing()
    imgui.Separator()
    imgui.Spacing()

    -- кнопки: отмена слева, публикация справа
    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.20, 1.0))
    if imgui.Button("Отмена##cr_cancel", imgui.ImVec2(half, 36)) then
        imgui.CloseCurrentPopup()
    end
    imgui.PopStyleColor(1)
    imgui.SameLine()
    local ready = (#missing == 0) and not MKT.loading
    imgui.PushStyleColor(imgui.Col.Button, ready and MKT.rainbow_btn(0.5) or imgui.ImVec4(0.22, 0.22, 0.26, 1.0))
    if imgui.Button("Опубликовать##cr_publish", imgui.ImVec2(half, 36)) and ready then
        local nick = MKT.nick()
        if not nick then
            MKT.set_status("Не удалось узнать ник. Зайдите на сервер", false)
        else
            MKT.queue_add("server=" .. MKT.enc(srv) .. "&item=" .. MKT.enc(name)
                .. "&price=" .. math.floor(price) .. "&type=" .. MKT.kind
                .. "&nick=" .. MKT.enc(nick) .. "&token=" .. MKT.enc(MKT.get_token())
                .. "&contact=" .. MKT.enc(contact)
                .. "&pass=" .. MKT.enc(ffi.string(MKT.buf_pass))
                .. "&home=" .. MKT.enc(MKT.home_servers[MKT.home])
                .. "&currency=" .. MKT.enc(MKT.currencies[MKT.currency].code)
                .. "&desc=" .. MKT.enc(MKT.desc_with_cd()))
            MKT.buf_item[0] = 0
            MKT.buf_price[0] = 0
            MKT.buf_contact[0] = 0
            MKT.buf_desc[0] = 0
            MKT.buf_csearch[0] = 0
            imgui.CloseCurrentPopup()
        end
    end
    imgui.PopStyleColor(1)
end

-- содержимое вкладки «Маркетплейс»
function MKT.draw()
    MKT.handle()

    if not MKT.prefs_loaded then
        MKT.prefs_loaded = true
        MKT.load_prefs()
        MKT.load_favs()
        MKT.prefs_last = MKT.prefs_key()
    end
    local pkey = MKT.prefs_key()
    if pkey ~= MKT.prefs_last then
        MKT.prefs_last = pkey
        MKT.save_prefs()
    end
    local srv = MKT.market

    if os.clock() - MKT.last_auto > 60 then
        MKT.last_auto = os.clock()
        MKT.need_list = true
    end
    if MKT.need_list and not MKT.loading then
        MKT.need_list = false
        MKT.send("list", "server=" .. MKT.enc(srv) .. "&token=" .. MKT.enc(MKT.get_token()))
    end

    local q = ru_lower(ffi.string(MKT.buf_search))
    q = (q:gsub("^%s+", ""):gsub("%s+$", ""))

    -- шапка: название, выбор сервера, кнопка выставить
    imgui.TextColored(imgui.ImVec4(1.0, 0.45, 0.35, 1.0), "●")
    imgui.SameLine()
    imgui.TextColored(accent_vec(1.3), "Prices Market")
    imgui.SameLine(math.max(120, imgui.GetWindowWidth() - 190))
    if MKT.pill("create", "+ Выставить", true, 130, 30) then
        MKT.edit_id = nil
        MKT.want_create = true
    end
    imgui.SameLine(imgui.GetWindowWidth() - 29)
    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0, 0, 0, 0))
    if imgui.Button(FA.CIRCLE_XMARK .. "##mkt_close", imgui.ImVec2(24, 24)) then
        main_window[0] = false
    end
    if imgui.IsItemHovered() then imgui.SetTooltip("Закрыть") end
    imgui.PopStyleColor(1)

    -- фильтры: все / сдам-продаю / куплю
    imgui.Spacing()
    -- кнопки ряда переносятся на новую строку, если не помещаются в окно
    local row_w = imgui.GetWindowWidth() - 24
    local row_x = 0
    local function row_pos(w)
        if row_x > 0 then
            if row_x + w > row_w then
                row_x = 0
            else
                imgui.SameLine()
                row_x = row_x + 8
            end
        end
        row_x = row_x + w
    end
    local tabs = { { "Все", "all" }, { "Сдам / продаю", "sell" }, { "Куплю", "buy" }, { "Избранное", "fav" }, { "Мои", "mine" } }
    for _, t in ipairs(tabs) do
        local tw = imgui.CalcTextSize(t[1]).x + 34
        row_pos(tw)
        if MKT.pill("tab_" .. t[2], t[1], MKT.tab == t[2], tw, 30) then
            MKT.tab = t[2]
        end
    end
    row_pos(120)
    if MKT.pill("refresh", "Обновить", false, 120, 30) then
        MKT.need_list = true
    end
    -- режим админа: пароль вводится в игре и хранится только в памяти, в файл не пишется
    row_pos(130)
    if MKT.pill("admin", MKT.admin_key_mem and "Админ: вкл" or "Админ", MKT.admin_key_mem ~= nil, 130, 30) then
        if MKT.admin_key_mem then
            MKT.admin_key_mem = nil
            MKT.set_status("Режим админа выключен", true)
        else
            MKT.want_admin = true
        end
    end
    imgui.Spacing()

    -- сортировка и фильтры
    imgui.PushItemWidth(170)
    if imgui.BeginCombo("##mkt_sort", MKT.sorts[MKT.sort][2]) then
        for i, so in ipairs(MKT.sorts) do
            if imgui.Selectable(so[2] .. "##mkt_sort_" .. i, i == MKT.sort) then
                MKT.sort = i
            end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()
    imgui.SameLine()
    imgui.PushItemWidth(90)
    if imgui.BeginCombo("##mkt_fcur", MKT.fcur_opts[MKT.fcur]) then
        for i, c in ipairs(MKT.fcur_opts) do
            if imgui.Selectable(c .. "##mkt_fc_" .. i, i == MKT.fcur) then
                MKT.fcur = i
            end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()
    imgui.SameLine()
    imgui.PushItemWidth(110)
    imgui.InputTextWithHint("##mkt_pmin", "цена от", MKT.buf_pmin, ffi.sizeof(MKT.buf_pmin))
    imgui.PopItemWidth()
    imgui.SameLine()
    imgui.PushItemWidth(110)
    imgui.InputTextWithHint("##mkt_pmax", "до", MKT.buf_pmax, ffi.sizeof(MKT.buf_pmax))
    imgui.PopItemWidth()
    imgui.SameLine()
    imgui.PushItemWidth(100)
    if imgui.BeginCombo("##mkt_age", MKT.ages[MKT.age_idx][1]) then
        for i, a in ipairs(MKT.ages) do
            if imgui.Selectable(a[1] .. "##mkt_age_" .. i, i == MKT.age_idx) then
                MKT.age_idx = i
            end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()
    imgui.Spacing()

    -- строка поиска
    imgui.PushItemWidth(-1)
    imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0.10, 0.10, 0.13, 1.0))
    imgui.InputTextWithHint("##mkt_search", "Поиск по названию предмета, например: нимб", MKT.buf_search, ffi.sizeof(MKT.buf_search))
    imgui.PopStyleColor(1)
    imgui.PopItemWidth()

    -- следить за предметами: уведомление в чат, когда появилось новое объявление
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint("##mkt_watch", "Следить за (через запятую), например: нимб, кастет", MKT.buf_watch, ffi.sizeof(MKT.buf_watch))
    imgui.PopItemWidth()

    -- статус и служебная строка
    if MKT.status ~= "" then
        local col = MKT.status_ok and imgui.ImVec4(0.45, 1.0, 0.55, 1.0) or imgui.ImVec4(1.0, 0.45, 0.45, 1.0)
        imgui.PushStyleColor(imgui.Col.Text, col)
        imgui.TextWrapped(MKT.status)
        imgui.PopStyleColor(1)
    end
    imgui.TextDisabled("Объявления без срока, удалить может только автор. " .. MKT.VERSION)
    imgui.Separator()

    -- карточки объявлений
    imgui.BeginChild("##mkt_list", imgui.ImVec2(-1, -1), false)
    local shown = 0
    local view = MKT.view(q)
    for i, it in ipairs(view) do
        do
            shown = shown + 1
            local is_buy = it.type == "buy"
            local cp = imgui.GetCursorScreenPos()
            local cw = imgui.GetContentRegionAvail().x
            local chov = imgui.IsMouseHoveringRect(cp, imgui.ImVec2(cp.x + cw, cp.y + 62))
            if chov then
                imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.17, 0.14, 0.11, 0.98))
                imgui.PushStyleColor(imgui.Col.Border, MKT.rainbow(i * 0.4))
            else
                imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.10, 0.10, 0.13, 0.95))
                imgui.PushStyleColor(imgui.Col.Border, accent_vec(0.9, 0.35))
            end
            imgui.BeginChild("##mkt_card_" .. i, imgui.ImVec2(-1, 62), true)
            local is_buy = it.type == "buy"
            local ikey = item_icon_key(it.item)
            local itex = ikey and UIFX.icon_tex(ikey) or nil
            if itex then
                imgui.Image(itex, imgui.ImVec2(44, 44))
            else
                imgui.Dummy(imgui.ImVec2(44, 44))
            end
            imgui.SameLine()
            imgui.BeginGroup()
            imgui.TextColored(is_buy and imgui.ImVec4(0.4, 0.7, 1.0, 1.0) or imgui.ImVec4(1.0, 0.75, 0.3, 1.0),
                is_buy and "КУПЛЮ" or "ПРОДАЮ")
            imgui.SameLine()
            imgui.Text(tostring(it.item) .. "  -  " .. MKT.fmt(it.price) .. " " .. tostring(it.currency or "VC"))
            imgui.TextDisabled("Ник: " .. tostring(it.nick) .. "  |  " .. tostring(it.home or "Vice-City") .. "  |  " .. MKT.age(it.created))
            imgui.EndGroup()
            local bx = imgui.GetWindowWidth()
            local fav_on = MKT.favs[tostring(it.id)] == true
            if not it.mine then
                imgui.SameLine(math.max(120, bx - 230))
                if imgui.Button((fav_on and "Из избранного" or "В избранное") .. "##mkt_fav_" .. i, imgui.ImVec2(100, 0)) then
                    MKT.favs[tostring(it.id)] = (not fav_on) or nil
                    MKT.save_favs()
                end
            end
            if it.mine then
                imgui.SameLine(math.max(120, bx - 230))
                if imgui.Button("Изменить##mkt_edit_" .. i, imgui.ImVec2(100, 0)) then
                    MKT.start_edit(it)
                end
                imgui.SameLine(math.max(120, bx - 120))
                if imgui.Button("Удалить##mkt_del_" .. i, imgui.ImVec2(100, 0)) and not MKT.loading then
                    MKT.confirm = { id = it.id, item = tostring(it.item), t0 = os.clock() }
                    MKT.want_confirm = true
                end
            elseif it.contact and it.contact ~= "" then
                imgui.SameLine(math.max(120, bx - 120))
                if imgui.Button("Написать##mkt_w_" .. i, imgui.ImVec2(100, 0)) then
                    MKT.open_link(it.contact)
                end
            end
            if imgui.IsWindowHovered() and not imgui.IsAnyItemHovered() and imgui.IsMouseClicked(0) then
                MKT.detail = it
                MKT.want_open = true
            end
            imgui.EndChild()
            imgui.PopStyleColor(2)
        end
    end
    -- подтверждение удаления: окно полностью непрозрачное, 3 секунды до кнопки «Удалить»
    if MKT.want_confirm then
        MKT.want_confirm = false
        imgui.OpenPopup("##mkt_confirm")
    end
    imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.09, 0.09, 0.12, 1.0))
    imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(1.0, 0.45, 0.45, 1.0))
    if imgui.BeginPopupModal("##mkt_confirm", nil, bit.bor(imgui.WindowFlags.NoMove, imgui.WindowFlags.NoResize, imgui.WindowFlags.NoCollapse)) then
        local c = MKT.confirm or { item = "", t0 = os.clock() }
        local left = 3 - (os.clock() - (c.t0 or 0))
        imgui.TextColored(imgui.ImVec4(1.0, 0.45, 0.45, 1.0), "Вы действительно хотите удалить объявление?")
        imgui.Spacing()
        imgui.Text(tostring(c.item or ""))
        imgui.Spacing()
        if left > 0 then
            imgui.TextDisabled("Сможете подтвердить через " .. math.ceil(left) .. " сек.")
        else
            imgui.TextColored(imgui.ImVec4(0.45, 1.0, 0.55, 1.0), "Можно подтвердить")
        end
        imgui.Spacing()
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.20, 1.0))
        if imgui.Button("Отмена##mkt_conf_no", imgui.ImVec2(150, 34)) then
            MKT.confirm = nil
            imgui.CloseCurrentPopup()
        end
        imgui.PopStyleColor(1)
        imgui.SameLine()
        local ready = left <= 0 and not MKT.loading
        imgui.PushStyleColor(imgui.Col.Button, ready and imgui.ImVec4(0.6, 0.15, 0.15, 1.0) or imgui.ImVec4(0.22, 0.22, 0.26, 1.0))
        if imgui.Button("Удалить##mkt_conf_yes", imgui.ImVec2(150, 34)) and ready then
            MKT.send("delete", "server=" .. MKT.enc(MKT.market) .. "&id=" .. MKT.enc(c.id)
                .. "&token=" .. MKT.enc(MKT.get_token())
                .. (c.admin and MKT.admin_key_mem and ("&admin=" .. MKT.enc(MKT.admin_key_mem)) or ""))
            MKT.confirm = nil
            imgui.CloseCurrentPopup()
        end
        imgui.PopStyleColor(1)
        imgui.EndPopup()
    end
    imgui.PopStyleColor(2)

    -- ввод пароля админа: в файл не сохраняется, живёт только до выключения или перезапуска скрипта
    if MKT.want_admin then
        MKT.want_admin = false
        ffi.copy(MKT.buf_admin, "")
        imgui.OpenPopup("##mkt_admin")
    end
    imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.09, 0.09, 0.12, 1.0))
    if imgui.BeginPopupModal("##mkt_admin", nil, bit.bor(imgui.WindowFlags.NoMove, imgui.WindowFlags.NoResize, imgui.WindowFlags.NoCollapse)) then
