    imgui.PushStyleColor(imgui.Col.PopupBg, imgui.ImVec4(0.07, 0.07, 0.09, 0.98))
    if imgui.BeginPopupModal("##mkt_detail", nil, bit.bor(imgui.WindowFlags.NoMove, imgui.WindowFlags.NoResize, imgui.WindowFlags.NoCollapse)) then
        local d = MKT.detail or {}
        local is_buy = d.type == "buy"
        local tag_col = is_buy and imgui.ImVec4(0.45, 0.72, 1.0, 1.0) or imgui.ImVec4(1.0, 0.75, 0.3, 1.0)

        -- переливающаяся полоса сверху
        do
            local dl = imgui.GetWindowDrawList()
            local pp = imgui.GetCursorScreenPos()
            local pw = imgui.GetContentRegionAvail().x
            local seg = 48
            for k = 0, seg - 1 do
                local x0 = pp.x + pw * k / seg
                local x1 = pp.x + pw * (k + 1) / seg
                local c = MKT.rainbow(k * 0.18)
                dl:AddRectFilled(imgui.ImVec2(x0, pp.y), imgui.ImVec2(x1, pp.y + 4), col32(c.x, c.y, c.z, 1.0))
            end
            imgui.Dummy(imgui.ImVec2(pw, 8))
        end

        -- шапка: тип сделки и название
        imgui.TextColored(tag_col, is_buy and "КУПЛЮ" or "ПРОДАЮ")
        imgui.SetWindowFontScale(1.45)
        imgui.TextColored(MKT.rainbow(0), tostring(d.item or ""))
        imgui.SetWindowFontScale(1.0)
        imgui.Spacing()

        -- цена крупно акцентом
        imgui.SetWindowFontScale(1.35)
        imgui.TextColored(MKT.rainbow(1.6), MKT.fmt(d.price) .. "  " .. tostring(d.currency or "VC"))
        imgui.SetWindowFontScale(1.0)
        imgui.Spacing()
        imgui.Separator()
        imgui.Spacing()

        -- сведения: подписи серым, значения белым
        local function info(label, value)
            imgui.TextDisabled(label)
            imgui.SameLine()
            imgui.SetCursorPosX(150)
            imgui.Text(tostring(value))
        end
        -- КД на тайники берём из описания и показываем отдельной строкой
        local cd_code, cd_n = tostring(d.desc or ""):match("КД: (%d+) %(%-(%d+)%)")
        if cd_code then
            info("КД на тайники", cd_code .. " - " .. cd_n .. " КД")
        end
        info("Продавец", d.nick or "")
        info("Родной сервер", d.home or "Vice-City")
        info("Контакт", d.contact or "не указан")
        imgui.Spacing()

        -- описание в отдельном блоке
        imgui.TextDisabled("Описание")
        imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.11, 0.11, 0.14, 1.0))
        imgui.BeginChild("##mkt_det_desc", imgui.ImVec2(-1, 170), true)
        local desc_clean = (tostring(d.desc or ""):gsub(" | КД: %d+ %(%-%d+%)", ""))
        local desc = (desc_clean ~= "") and desc_clean or "Продавец не добавил описание"
        imgui.PushTextWrapPos(imgui.GetCursorPosX() + imgui.GetWindowWidth() - 24)
        imgui.TextWrapped(tostring(desc))
        imgui.PopTextWrapPos()
        imgui.EndChild()
        imgui.PopStyleColor(1)
        imgui.Spacing()

        -- кнопки
        if d.contact and d.contact ~= "" then
            imgui.PushStyleColor(imgui.Col.Button, MKT.rainbow_btn(2.2))
            if imgui.Button("Написать продавцу##mkt_det_w", imgui.ImVec2(-1, 36)) then
                MKT.open_link(d.contact)
            end
            imgui.PopStyleColor(1)
        end
        if MKT.admin_key_mem and not d.mine then
            imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.55, 0.12, 0.12, 1.0))
            if imgui.Button("Удалить (админ)##mkt_det_admdel", imgui.ImVec2(-1, 30)) then
                MKT.confirm = { id = d.id, item = tostring(d.item), t0 = os.clock(), admin = true }
                MKT.want_confirm = true
            end
            imgui.PopStyleColor(1)
        end
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.20, 1.0))
        if imgui.Button("Копировать ник##mkt_det_nick", imgui.ImVec2(-1, 30)) then
            setClipboardText(tostring(d.nick or ""))
            MKT.set_status("Ник скопирован: " .. tostring(d.nick or ""), true)
        end
        if imgui.Button("Закрыть##mkt_det_close", imgui.ImVec2(-1, 30)) then
            imgui.CloseCurrentPopup()
        end
        imgui.PopStyleColor(1)
        imgui.EndPopup()
    end
    imgui.PopStyleColor(1)

    if shown == 0 then
        if MKT.loading then
            imgui.TextDisabled("Загружаем...")
        elseif q ~= "" then
            imgui.TextDisabled("Ничего не найдено по запросу")
        else
            imgui.TextDisabled("Пока объявлений нет. Станьте первым!")
        end
    end
    imgui.EndChild()
end

